public sealed interface PaymentResult permits Success, Failure, Pending {
}

public final class Success implements PaymentResult {
    private final String transactionId;
    public Success(String transactionId) { this.transactionId = transactionId; }
    public String getTransactionId() { return transactionId; }
}

public final class Failure implements PaymentResult {
    private final String errorCode;
    public Failure(String errorCode) { this.errorCode = errorCode; }
    public String getErrorCode() { return errorCode; }
}

public non-sealed class Pending implements PaymentResult {
    private final long retryAfterSeconds;
    public Pending(long retryAfterSeconds) { this.retryAfterSeconds = retryAfterSeconds; }
    public long getRetryAfterSeconds() { return retryAfterSeconds; }
}
